"""L1 -- run a detector you did not train.

Station: DATA -> MODEL -> TRAIN -> EVALUATE -> DEPLOY
                                              ^^^^^^

YOLOv8-nano is about three million numbers fitted to somebody else's photograph
collection. You will not read it, retrain it, or understand what any individual
weight does, and none of that stops you from using it correctly. Knowing which
of those things matter is most of the job.

The weights ship in provided/models/. Load them by path. Nothing here should
reach the network -- a grader that depends on a download is a grader that fails
on the day the download is down.
"""

from __future__ import annotations

import csv
from pathlib import Path

PROVIDED = Path(__file__).resolve().parent.parent / "provided"
WEIGHTS = PROVIDED / "models" / "yolov8n.pt"
CSV_COLUMNS = ["filename", "label", "score", "x1", "y1", "x2", "y2"]



def load_detector(weights_path=WEIGHTS):
    """Return an object-detection model loaded from `weights_path`.

    The returned object is whatever the library hands back; later functions in
    this module are the only things that touch it, so its type is your choice.

    Hint: `ultralytics.YOLO` takes a path.
    """
    # Imported here, not at module level: torch + ultralytics take most of a
    # minute to import, and `import facedetect` should stay cheap and inert.
    from ultralytics import YOLO

    weights_path = Path(weights_path)
    if not weights_path.is_file():
        # Refuse rather than let ultralytics treat an unknown name as something
        # to download -- nothing in this package touches the network.
        raise FileNotFoundError(f"YOLO weights not found at {weights_path}")
    return YOLO(str(weights_path))


def detect_objects(model, image_path, conf=0.25):
    """Run `model` over one image and return its detections.

    Returns a list of dicts, one per detection, each with keys:
        "label"  str    the class name, e.g. "stop sign"
        "score"  float  confidence in [0, 1]
        "box"    tuple  (x1, y1, x2, y2) in pixels, floats, top-left origin

    Detections below `conf` are excluded. An image with nothing in it returns
    an empty list -- not None, and not a list with a placeholder in it.

    Hint: the results object exposes boxes with `.cls`, `.conf` and `.xyxy`,
    and the model carries a mapping from class index to name.
    """
    # Passing the path lets ultralytics do its own read (BGR via OpenCV),
    # which is the colour order the model was trained with.
    results = model.predict(str(image_path), conf=conf, verbose=False)
    detections = []
    for result in results:
        names = result.names
        boxes = result.boxes
        if boxes is None or len(boxes) == 0:
            continue
        xyxy = boxes.xyxy.cpu().numpy()
        scores = boxes.conf.cpu().numpy()
        classes = boxes.cls.cpu().numpy().astype(int)
        for (x1, y1, x2, y2), score, cls in zip(xyxy, scores, classes):
            if float(score) < conf:
                continue
            detections.append({
                "label": str(names[int(cls)]),
                "score": float(score),
                "box": (float(x1), float(y1), float(x2), float(y2)),
            })
    return detections


def write_detections_csv(rows, out_path):
    """Write detection rows to `out_path` as CSV.

    Columns, in this order: filename, label, score, x1, y1, x2, y2

    `rows` is a list of dicts with those keys. Write a header. Scores and
    coordinates are written as plain numbers; the grader reads this file back
    with `csv.DictReader` and converts, so don't format them for display.
    """
    with open(out_path, "w", newline="") as fh:
        writer = csv.DictWriter(fh, fieldnames=CSV_COLUMNS, extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            writer.writerow({k: row[k] for k in CSV_COLUMNS})


def run_scenes(out_path="detections.csv", scenes_dir=PROVIDED / "scenes",
               conf=0.25, model=None):
    """Run the detector over every provided scene and write `out_path`.

    Returns the list of rows written. This is the L1 deliverable; it only runs
    when called (or via `python -m facedetect.detect`), never on import.
    """
    if model is None:
        model = load_detector()
    rows = []
    for image_path in sorted(Path(scenes_dir).glob("*.png")):
        for d in detect_objects(model, image_path, conf=conf):
            x1, y1, x2, y2 = d["box"]
            rows.append({"filename": image_path.name, "label": d["label"],
                         "score": d["score"], "x1": x1, "y1": y1,
                         "x2": x2, "y2": y2})
    write_detections_csv(rows, out_path)
    return rows


if __name__ == "__main__":
    written = run_scenes()
    print(f"wrote detections.csv ({len(written)} detections)")
